(function(){
function decode(value){if(!value)return null;try{var text=decodeURIComponent(Array.prototype.map.call(atob(value.replace(/-/g,"+").replace(/_/g,"/")),function(c){return "%"+("00"+c.charCodeAt(0).toString(16)).slice(-2);}).join(""));return JSON.parse(text);}catch(e){return null;}}
function encode(value){var bytes=unescape(encodeURIComponent(JSON.stringify(value)));return btoa(bytes).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");}
function el(tag,className,text){var node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function money(value,currency){var number=Number(value)||0;try{return new Intl.NumberFormat("sr-RS",{style:"currency",currency:currency&&currency.length===3?currency:"RSD",maximumFractionDigits:2}).format(number);}catch(e){return number.toFixed(2)+" "+(currency||"RSD");}}
function clip(value,max){value=String(value||"").trim();return value.length>max?value.slice(0,max):value;}
document.querySelectorAll(".wf-instance[data-wf-component=\"product-list\"]").forEach(function(host){
if(host.dataset.wfCatalogReady==="true")return;
host.dataset.wfCatalogReady="true";
var root=host.querySelector(".wf-catalog");
if(!root)return;
var results=root.querySelector("[data-wf-results]"),filters=root.querySelector("[data-wf-filters]"),status=root.querySelector("[data-wf-status]"),count=root.querySelector("[data-wf-count]"),pagination=root.querySelector("[data-wf-pagination]"),search=root.querySelector("[data-wf-search]"),category=root.querySelector("[data-wf-category]"),sort=root.querySelector("[data-wf-sort]"),form=root.querySelector("[data-wf-search-form]"),chips=root.querySelector("[data-wf-chips]"),filterToggle=root.querySelector("[data-wf-filters-toggle]");
var input=decode(host.dataset.wfProviderInput)||{page:1,limit:24,sort:"default"};
input.page=input.page||1;input.limit=input.limit||24;input.sort=input.sort||"default";input.filters=input.filters||[];input.attributes=input.attributes||[];
var lockedCategory=input.category&&input.category!=="all"?String(input.category):"";
if(lockedCategory){input.category=lockedCategory;var categoryLabel=category&&category.closest("label");if(categoryLabel)categoryLabel.hidden=true;}
var lockedBrands=[];
(input.filters||[]).forEach(function(group){if(group.field==="field11"){(group.values||[]).forEach(function(value){if(lockedBrands.indexOf(String(value))<0)lockedBrands.push(String(value));});}});
function restoreLockedBrands(){lockedBrands.forEach(function(value){updateStored("filters","field","field11",value);});}
var facetMemory=null;
var pendingId="";
var serial=0;
var fromHistory=false;
if(host.hasAttribute("data-wf-provider-preview")||host.hasAttribute("data-wf-provider-preview-error"))host.dataset.wfCatalogBridge="true";
function requestId(){serial+=1;var suffix=Math.random().toString(36).replace(/[^a-z0-9]/g,"").slice(0,8);var prefix=("00000000"+serial.toString(36)).slice(-8);return (prefix+suffix).slice(0,40);}
function selected(kind,key,value){return (input[kind]||[]).some(function(group){return (group.field===key||group.name===key)&&group.values.indexOf(value)>=0;});}
function removeValue(kind,key,value){if(kind==="filters"&&key==="field11"&&lockedBrands.indexOf(value)>=0)return;var keyName=kind==="filters"?"field":"name";input[kind]=(input[kind]||[]).filter(function(group){if(group[keyName]!==key)return true;group.values=group.values.filter(function(item){return item!==value;});return group.values.length>0;});input.page=1;}
function updateFilter(kind,key,value,checked){if(kind==="filters"&&key==="field11"&&lockedBrands.indexOf(value)>=0&&!checked)return;var keyName=kind==="filters"?"field":"name",list=(input[kind]||[]).filter(function(group){return group[keyName]!==key;}),current=(input[kind]||[]).find(function(group){return group[keyName]===key;}),values=current?current.values.slice():[];if(checked&&values.indexOf(value)<0)values.push(value);if(!checked)values=values.filter(function(item){return item!==value;});if(values.length){var group={values:values};group[keyName]=key;list.push(group);}input[kind]=list;input.page=1;load(true);}
function resetInput(){input.q="";input.category=lockedCategory||"all";input.sort="default";input.page=1;input.filters=[];input.attributes=[];restoreLockedBrands();search.value="";sort.value="default";if(category)category.value=input.category;}
function readUrl(fromPop){var params=new URLSearchParams(window.location.search);if(!urlHasCatalogState()){if(!fromPop)return;input.q="";input.category=lockedCategory||"all";input.sort="default";input.page=1;input.filters=[];input.attributes=[];restoreLockedBrands();if(search)search.value="";if(sort)sort.value="default";if(category)category.value=input.category;return;}input.q=params.has("q")?clip(params.get("q"),160):"";input.category=lockedCategory||(params.has("category")?(clip(params.get("category"),80)||"all"):"all");input.sort=params.has("sort")?(clip(params.get("sort"),20)||"default"):"default";input.page=1;if(params.has("page")){var page=parseInt(params.get("page"),10);if(page>0&&page<100000)input.page=page;}input.filters=[];input.attributes=[];params.getAll("df").slice(0,50).forEach(function(item){var parts=String(item).split(":");if(parts.length<2)return;var field=clip(parts.shift(),40),value=clip(parts.join(":"),160);if(!/^[a-z0-9]+$/.test(field)||!value)return;updateStored("filters","field",field,value);});params.getAll("da").slice(0,50).forEach(function(item){var parts=String(item).split(":");if(parts.length<2)return;var name=clip(parts.shift(),120),value=clip(parts.join(":"),160);if(!name||!value)return;updateStored("attributes","name",name,value);});restoreLockedBrands();search.value=input.q||"";sort.value=input.sort||"default";category.value=input.category||"all";}
function updateStored(kind,keyName,key,value){var current=(input[kind]||[]).find(function(group){return group[keyName]===key;});if(!current){current={values:[]};current[keyName]=key;input[kind].push(current);}if(current.values.indexOf(value)<0)current.values.push(value);}
function urlHasCatalogState(){var params=new URLSearchParams(window.location.search);return params.has("q")||params.has("category")||params.has("sort")||params.has("page")||params.has("df")||params.has("da");}
function writeUrl(push){var params=new URLSearchParams(window.location.search);function setOrDelete(key,value){if(value)params.set(key,value);else params.delete(key);}setOrDelete("q",input.q||"");setOrDelete("category",!lockedCategory&&input.category&&input.category!=="all"?input.category:"");setOrDelete("sort",input.sort&&input.sort!=="default"?input.sort:"");setOrDelete("page",input.page&&input.page!==1?String(input.page):"");params.delete("df");params.delete("da");(input.filters||[]).forEach(function(group){(group.values||[]).forEach(function(value){if(group.field==="field11"&&lockedBrands.indexOf(value)>=0)return;params.append("df",group.field+":"+value);});});(input.attributes||[]).forEach(function(group){(group.values||[]).forEach(function(value){params.append("da",group.name+":"+value);});});var query=params.toString();var next=window.location.pathname+(query?"?"+query:"")+window.location.hash;var current=window.location.pathname+window.location.search+window.location.hash;if(next===current)return;var historyState={wfCatalog:host.dataset.wfInstance||""};if(push)history.pushState(historyState,"",next);else history.replaceState(historyState,"",next);}
function renderChips(){if(!chips)return;chips.innerHTML="";var active=0;function add(label,remove){active+=1;var button=el("button","",label+" ×");button.type="button";button.addEventListener("click",function(){remove();load(true);});chips.appendChild(button);}if(input.q)add(input.q,function(){input.q="";search.value="";input.page=1;});if(!lockedCategory&&input.category&&input.category!=="all")add(input.category,function(){input.category="all";category.value="all";input.page=1;});(input.filters||[]).forEach(function(group){(group.values||[]).forEach(function(value){if(group.field==="field11"&&lockedBrands.indexOf(value)>=0)return;add(value,function(){removeValue("filters",group.field,value);});});});(input.attributes||[]).forEach(function(group){(group.values||[]).forEach(function(value){add(value,function(){removeValue("attributes",group.name,value);});});});if(active){var clear=el("button","","Očisti sve");clear.type="button";clear.setAttribute("data-wf-clear","true");clear.addEventListener("click",function(){resetInput();load(true);});chips.appendChild(clear);}if(filterToggle)filterToggle.textContent=active?"Filteri ("+active+")":"Filteri";}
function normalized(payload){if(Array.isArray(payload))return{items:payload,total:payload.length,page:1,limit:payload.length||24,filters:{categories:[],direct:[],attributes:[]}};return payload&&Array.isArray(payload.items)?payload:{items:[],total:0,page:1,limit:24,filters:{categories:[],direct:[],attributes:[]}};}
function renderFilters(data){var facets=data.filters||{};if(filters&&filters.querySelector("details")){facetMemory={};filters.querySelectorAll("details[data-wf-facet]").forEach(function(node){facetMemory[node.getAttribute("data-wf-facet")]=node.open;});}if(category){category.innerHTML="";var all=el("option","","Sve kategorije");all.value="all";category.appendChild(all);if(!lockedCategory){(facets.categories||[]).forEach(function(item){var option=el("option","",item.label+" ("+item.count+")");option.value=item.value;category.appendChild(option);});category.value=input.category||"all";}}filters.innerHTML="";function rememberOpen(key,initial){if(facetMemory&&Object.prototype.hasOwnProperty.call(facetMemory,key))return facetMemory[key];return initial;}function group(title,facetKey,values,checked,onChange,initialOpen){if(facetKey==="filter:field11"&&lockedBrands.length)return;if(!values||values.length<2)return;var details=el("details","wf-catalog__filter");details.setAttribute("data-wf-facet",facetKey);details.open=rememberOpen(facetKey,initialOpen);var summary=el("summary","",title),list=el("div","wf-catalog__filter-list");values.forEach(function(item){var label=el("label"),box=el("input"),name=el("span","",item.label),amount=el("small","",String(item.count));box.type="checkbox";box.checked=checked(item.value);box.addEventListener("change",function(){onChange(item.value,box.checked);});label.appendChild(box);label.appendChild(name);label.appendChild(amount);list.appendChild(label);});details.appendChild(summary);details.appendChild(list);filters.appendChild(details);}if(!lockedCategory)group("Kategorija","category",facets.categories||[],function(value){return input.category===value;},function(value,checked){input.category=checked?value:"all";if(category)category.value=input.category;input.page=1;load(true);},true);(facets.direct||[]).forEach(function(item){group(item.label,"filter:"+item.field,item.values,function(value){return selected("filters",item.field,value);},function(value,checked){updateFilter("filters",item.field,value,checked);},false);});(facets.attributes||[]).forEach(function(item){group(item.name,"attribute:"+item.name,item.values,function(value){return selected("attributes",item.name,value);},function(value,checked){updateFilter("attributes",item.name,value,checked);},false);});if(!filters.children.length)filters.appendChild(el("p","wf-catalog__status","Filteri nisu dostupni za ovaj skup podataka."));}
function renderProducts(data){results.innerHTML="";if(!data.items.length){results.appendChild(el("p","wf-catalog__empty","Nema proizvoda za izabrane uslove."));return;}data.items.forEach(function(item){var card=el("article","wf-product"),link=el("a","wf-product__link"),media=el("div","wf-product__media"),image=el("img"),content=el("div","wf-product__content"),meta=[];link.href="/proizvod?id="+encodeURIComponent(item.id||"");image.src=item["image-url"]||"/commonAssets/Images/coming_soon_transparent.png";image.alt=item.name||"";image.loading="lazy";image.decoding="async";media.appendChild(image);if(root.dataset.showBrand==="true"&&item.brand)meta.push(item.brand);if(root.dataset.showCategory==="true"&&item.category)meta.push(item.category);if(meta.length)content.appendChild(el("p","wf-product__meta",meta.join(" · ")));content.appendChild(el("h2","",item.name||item.id));var footer=el("div","wf-product__footer");footer.appendChild(el("strong","wf-product__price",money(item.price,item.currency)));if(root.dataset.showStock==="true"){var known=item["stock-known"]!==false,stock=el("span","wf-product__stock",known?(Number(item.stock)>0?"Na stanju: "+item.stock:"Nema na stanju"):"Stanje na upit");stock.dataset.empty=known&&Number(item.stock)<=0?"true":"false";stock.dataset.known=known?"true":"false";footer.appendChild(stock);}content.appendChild(footer);link.appendChild(media);link.appendChild(content);card.appendChild(link);results.appendChild(card);});}
function renderPagination(data){pagination.innerHTML="";var pages=Math.max(1,Math.ceil(data.total/Math.max(1,data.limit)));if(pages<=1)return;function button(label,page,disabled,current){var b=el("button","",label);b.type="button";b.disabled=disabled;if(current)b.setAttribute("aria-current","true");b.addEventListener("click",function(){input.page=page;load(true);});pagination.appendChild(b);}button("Prethodna",Math.max(1,data.page-1),data.page<=1,false);var start=Math.max(1,data.page-2),end=Math.min(pages,start+4);start=Math.max(1,end-4);for(var i=start;i<=end;i++)button(String(i),i,false,i===data.page);button("Sledeća",Math.min(pages,data.page+1),data.page>=pages,false);}
function render(payload){var data=normalized(payload);status.textContent="";status.removeAttribute("data-error");count.textContent=data.total+" "+(data.total===1?"proizvod":"proizvoda");renderFilters(data);renderProducts(data);renderPagination(data);renderChips();}
function applyPayload(payload){if(pendingId&&arguments.length){}render(payload.data!==undefined?payload.data:payload);}
function load(push,scroll){if(scroll!==false&&root.scrollIntoView)root.scrollIntoView({behavior:"smooth",block:"start"});var id=requestId();pendingId=id;status.textContent="Učitavanje…";status.removeAttribute("data-error");writeUrl(push===true);renderChips();if(host.dataset.wfCatalogBridge==="true"){window.parent.postMessage({type:"elastyc-webfront-catalog-provider-v1",pageKey:host.dataset.wfPage||"",instanceKey:host.dataset.wfInstance||"",input:input,requestId:id},"*");return;}var url=new URL(host.dataset.wfProviderUrl,window.location.href);url.searchParams.set("wf_input",encode(input));fetch(url.toString(),{credentials:"same-origin",headers:{Accept:"application/json"}}).then(function(response){if(!response.ok)throw new Error("HTTP "+response.status);return response.json();}).then(function(payload){if(pendingId!==id)return;applyPayload(payload);}).catch(function(error){if(pendingId!==id)return;status.textContent=error&&error.message?error.message:"Katalog trenutno nije dostupan.";status.dataset.error="true";});}
form.addEventListener("submit",function(event){event.preventDefault();input.q=search.value.trim();if(!lockedCategory&&category)input.category=category.value;input.sort=sort.value;input.page=1;load(true);});
if(category)category.addEventListener("change",function(){if(lockedCategory)return;input.category=category.value;input.page=1;load(true);});
sort.addEventListener("change",function(){input.sort=sort.value;input.page=1;load(true);});
if(filterToggle)filterToggle.addEventListener("click",function(){root.dataset.filtersOpen=root.dataset.filtersOpen==="true"?"false":"true";});
root.querySelectorAll("[data-wf-view]").forEach(function(button){function sync(){button.setAttribute("aria-pressed",root.dataset.layout===button.dataset.wfView?"true":"false");}sync();button.addEventListener("click",function(){root.dataset.layout=button.dataset.wfView;root.querySelectorAll("[data-wf-view]").forEach(function(other){other.setAttribute("aria-pressed",other===button?"true":"false");});});});
window.addEventListener("message",function(event){if(event.source!==window.parent)return;var data=event.data;if(!data||data.type!=="elastyc-webfront-catalog-provider-result-v1")return;if(data.requestId!==pendingId||data.instanceKey!==host.dataset.wfInstance)return;if(!data.ok){status.textContent=data.error||"Katalog trenutno nije dostupan.";status.dataset.error="true";return;}applyPayload({data:data.data});});
window.addEventListener("popstate",function(){readUrl(true);load(false);});
readUrl();
var preview=decode(host.dataset.wfProviderPreview);
var previewError=host.dataset.wfProviderPreviewError||"";
if(host.dataset.wfCatalogBridge==="true"&&preview&&!urlHasCatalogState()){render(preview);writeUrl(false);}else if(previewError){status.textContent=previewError;status.dataset.error="true";renderChips();}else load(false,false);
});
